PREFIX brick: <brick://>
PREFIX ref: <ref://>
SELECT ?point ?pointClass ?tsid ?sensor ?sensorURI
WHERE {
  ?zone a brick:Zone ; brick:hasSubregion? .
  ?point brick:isPointOf ?zone ; a ?pointClass .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
}
LIMIT 100

SELECT ?point ?cls ?ext ?tsid
WHERE {
  ?zone a brick:Zone .
  ?point brick:hasLocation ?zone .
  ?point a brick:Zone_Air_Temperature_Sensor .
  FILTER (CONTAINS(str(?zone), "Zone_F3_Z01"))
  OPTIONAL { ?point ref:hasExternalReference ?e ; ?e ref:hasTimeseriesId ?tsid }
}

